def test_basic_functionality():
    # Rate: 1 token per second, Burst: 2
    # Key1 starts with 2 tokens.
    l = Limiter(1, 2)
    assert l.allow("a", 0.0) is True  # 1 token left
    assert l.allow("a", 0.0) is True  # 0 tokens left
    assert l.allow("a", 0.0) is False # 0 tokens left

def test_refill():
    # Rate: 1 token per second, Burst: 2
    l = Limiter(1, 2)
    assert l.allow("a", 0.0) is True  # 1 left
    assert l.allow("a", 0.0) is True  # 0 left
    assert l.allow("a", 1.0) is True  # Refilled 1, consumed 1, 0 left
    assert l.allow("a", 1.0) is False # 0 left

def test_burst():
    l = Limiter(1, 5)
    for i in range(5):
        assert l.allow("a", 0.0) is True
    assert l.allow("a", 0.0) is False

def test_independent_keys():
    l = Limiter(1, 1)
    assert l.allow("a", 0.0) is True
    assert l.allow("a", 0.0) is False
    assert l.allow("b", 0.0) is True  # Key b starts full

def test_time_backwards():
    l = Limiter(1, 2)
    l.allow("a", 10.0)
    try:
        l.allow("a", 5.0)
    except ValueError:
        pass
    else:
        assert False, "Should have raised ValueError for backward time"

def test_invalid_params():
    try:
        Limiter(0, 1)
    except ValueError:
        pass
    else:
        assert False, "Should have raised ValueError for rate <= 0"

    try:
        Limiter(1, 0.5)
    except ValueError:
        pass
    else:
        assert False, "Should have raised ValueError for burst < 1"

if __name__ == "__main__":
